export interface AuditEntry {
  actor: string;
  action: string;
  route: string;
  outcome: "success" | "denied" | "failed";
  occurred_at: string;
  request_id?: string;
}

/** One audit entry for an admin action, as stored for the SOC 2 evidence. */
export function auditEntry(req: AdminRequest, action: string, now: Date = new Date()): AuditEntry {
  const requestId = req.headers["x-request-id"] || req.headers["X-Request-ID"];

  return {
    actor: req.actor,
    action,
    route: `${req.method} ${req.path}`,
    outcome: "success",
    occurred_at: now.toISOString(),
    ...(requestId && { request_id: requestId }),
  };
}

